import { expect, test } from "vitest"

import { albumData } from "@/data/album"

/**
 * Consistency of the published data.
 *
 * `src/data/album.ts` is generated by the publish pipeline in the end state and
 * hand-written until then, so these tests are the guard on whichever writer ran:
 * the page trusts the data and does no filtering of its own (spec §5.1).
 */
test("id 不重复", () => {
  const ids = albumData.photos.map((p) => p.id)
  expect(new Set(ids).size).toBe(ids.length)
})

test("每张照片的 placeId 都能找到对应 Place", () => {
  const places = new Set(albumData.places.map((p) => p.id))
  for (const item of albumData.photos) {
    if (item.placeId) expect(places.has(item.placeId), item.placeId).toBe(true)
  }
})

test("相册引用的照片都存在，照片引用的相册也都存在", () => {
  const albumIds = new Set(albumData.albums.map((a) => a.id))
  const photoIds = new Set(albumData.photos.map((p) => p.id))
  for (const item of albumData.photos) {
    for (const id of item.albumIds) expect(albumIds.has(id), id).toBe(true)
  }
  for (const album of albumData.albums) {
    for (const id of album.photoIds) expect(photoIds.has(id), id).toBe(true)
  }
})

test("每张照片都是 webp", () => {
  for (const item of albumData.photos) expect(item.src).toMatch(/\.webp$/)
})

test("bucket 就是 takenAt 的前 7 位；没有拍摄时间时两者都是 null", () => {
  for (const item of albumData.photos) {
    if (item.takenAt) {
      expect(item.bucket).toBe(item.takenAt.slice(0, 7))
    } else {
      expect(item.bucket).toBeNull()
    }
  }
})

test("places 的 id 不重复，且经纬度是有限数", () => {
  const ids = albumData.places.map((p) => p.id)
  expect(new Set(ids).size).toBe(ids.length)
  for (const place of albumData.places) {
    expect(Number.isFinite(place.lat)).toBe(true)
    expect(Number.isFinite(place.lon)).toBe(true)
  }
})
